        unit = None
        if movement.source_doc_type == "STOCK_INWARD":
            inward = StockInward.objects.using(database).filter(
                pk=movement.source_doc_id,
            ).first()
            if inward:
                unit = inward.unit
        elif movement.source_doc_type == "OPENING" and movement.source_doc_id == 1:
            if item.item_type == "RAW":
                conversion = UnitConversion.objects.using(database).filter(
                    item_id=item.pk,
                ).order_by("-to_base_multiplier").first()
                if conversion:
                    unit = conversion.unit
            else:
                unit = item.base_unit

        if not unit:
            continue
